{"content": "import pytest
from fastapi.dependencies.models import Dependant
import inspect

class MyDep:
    async def __call__(self):
        return "hello"

def test_class_dependency_is_not_coroutine_callable():
    dep = Dependant(call=MyDep)
    assert dep.is_coroutine_callable is False

class MyGenDep:
    def __call__(self):
        yield "hello"

def test_class_dependency_is_not_gen_callable():
    dep = Dependant(call=MyGenDep)
    assert dep.is_gen_callable is False

class MyAsyncGenDep:
    async def __call__(self):
        yield "hello"

def test_class_dependency_is_not_async_gen_callable():
    dep = Dependant(call=MyAsyncGenDep)
    assert dep.is_async_gen_callable is False
", "filepath": "tests/test_regression_class_dependency.py"}

